" class="type MongoDB\Driver\Monitoring\ServerHeartbeatFailedEvent" style="color:#EAB766">MongoDB\Driver\Monitoring\ServerHeartbeatFailedEvent</a></span> <span class="parameter" style="color:#3A95FF">\$event</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">abstract</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/mongodb-driver-monitoring-sdamsubscriber.serverheartbeatstarted.php" class="methodname" style="color:#CC7832">serverHeartbeatStarted</a></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.mongodb-driver-monitoring-serverheartbeatstartedevent.php" class="type MongoDB\Driver\Monitoring\ServerHeartbeatStartedEvent" style="color:#EAB766">MongoDB\Driver\Monitoring\ServerHeartbeatStartedEvent</a></span> <span class="parameter" style="color:#3A95FF">\$event</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">abstract</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/mongodb-driver-monitoring-sdamsubscriber.serverheartbeatsucceeded.php" class="methodname" style="color:#CC7832">serverHeartbeatSucceeded</a></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.mongodb-driver-monitoring-serverheartbeatsucceededevent.php" class="type MongoDB\Driver\Monitoring\ServerHeartbeatSucceededEvent" style="color:#EAB766">MongoDB\Driver\Monitoring\ServerHeartbeatSucceededEvent</a></span> <span class="parameter" style="color:#3A95FF">\$event</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">abstract</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/mongodb-driver-monitoring-sdamsubscriber.serveropening.php" class="methodname" style="color:#CC7832">serverOpening</a></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.mongodb-driver-monitoring-serveropeningevent.php" class="type MongoDB\Driver\Monitoring\ServerOpeningEvent" style="color:#EAB766">MongoDB\Driver\Monitoring\ServerOpeningEvent</a></span> <span class="parameter" style="color:#3A95FF">\$event</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">abstract</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/mongodb-driver-monitoring-sdamsubscriber.topologychanged.php" class="methodname" style="color:#CC7832">topologyChanged</a></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.mongodb-driver-monitoring-topologychangedevent.php" class="type MongoDB\Driver\Monitoring\TopologyChangedEvent" style="color:#EAB766">MongoDB\Driver\Monitoring\TopologyChangedEvent</a></span> <span class="parameter" style="color:#3A95FF">\$event</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">abstract</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/mongodb-driver-monitoring-sdamsubscriber.topologyclosed.php" class="methodname" style="color:#CC7832">topologyClosed</a></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.mongodb-driver-monitoring-topologyclosedevent.php" class="type MongoDB\Driver\Monitoring\TopologyClosedEvent" style="color:#EAB766">MongoDB\Driver\Monitoring\TopologyClosedEvent</a></span> <span class="parameter" style="color:#3A95FF">\$event</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">abstract</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/mongodb-driver-monitoring-sdamsubscriber.topologyopening.php" class="methodname" style="color:#CC7832">topologyOpening</a></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.mongodb-driver-monitoring-topologyopeningevent.php" class="type MongoDB\Driver\Monitoring\TopologyOpeningEvent" style="color:#EAB766">MongoDB\Driver\Monitoring\TopologyOpeningEvent</a></span> <span class="parameter" style="color:#3A95FF">\$event</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div>   }</div>  </div>  <div class="section">   <h2 class="title">更新日志</h2>   <table class="doctable informaltable">         <thead>      <tr>       <th>版本</th>       <th>说明</th>      </tr>     </thead>     <tbody class="tbody">             <tr>        <td>PECL mongodb 2.0.0</td>        <td>         之前声明为暂定的返回类型现在已被强制执行。        </td>       </tr>             <tr>        <td>PECL mongodb 1.15.0</td>        <td>         在 PHP 8.0 及更高版本中，方法的返回类型被声明为暂定（tentative），         这会导致在实现该接口但未声明相应返回类型的代码中触发弃用提示。         可以添加 <span class="code">#[ReturnTypeWillChange]</span> 属性来消除该弃用提示。        </td>       </tr>     </tbody>       </table>  </div> </div>   <h2>目录</h2><ul class="chunklist chunklist_reference"><li>{@link MongoDB\Driver\Monitoring\SDAMSubscriber::serverChanged} — Notification method for a server description change</li><li>{@link MongoDB\Driver\Monitoring\SDAMSubscriber::serverClosed} — Notification method for closing a server</li><li>{@link MongoDB\Driver\Monitoring\SDAMSubscriber::serverHeartbeatFailed} — Notification method for a failed server heartbeat</li><li>{@link MongoDB\Driver\Monitoring\SDAMSubscriber::serverHeartbeatStarted} — Notification method for a started server heartbeat</li><li>{@link MongoDB\Driver\Monitoring\SDAMSubscriber::serverHeartbeatSucceeded} — Notification method for a successful server heartbeat</li><li>{@link MongoDB\Driver\Monitoring\SDAMSubscriber::serverOpening} — Notification method for opening a server</li><li>{@link MongoDB\Driver\Monitoring\SDAMSubscriber::topologyChanged} — Notification method for a topology description change</li><li>{@link MongoDB\Driver\Monitoring\SDAMSubscriber::topologyClosed} — Notification method for closing the topology</li><li>{@link MongoDB\Driver\Monitoring\SDAMSubscriber::topologyOpening} — Notification method for opening the topology</li></ul></div>
 * 
 * @since 1.13.0
 * @link https://www.php.net/manual/en/class.mongodb-driver-monitoring-sdamsubscriber.php
