interface SDAMSubscriber extends Subscriber
{
    /**
 * <div id="mongodb-driver-monitoring-sdamsubscriber.serverchanged" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\Driver\Monitoring\SDAMSubscriber::serverChanged</h1>  <p class="verinfo">(mongodb &gt;=1.13.0)</p><p class="refpurpose"><span class="refname">MongoDB\Driver\Monitoring\SDAMSubscriber::serverChanged</span> — <span class="dc-title">Notification method for a server description change</span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-driver-monitoring-sdamsubscriber.serverchanged-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">abstract</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\Driver\Monitoring\SDAMSubscriber::serverChanged</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.mongodb-driver-monitoring-serverchangedevent.php" class="type MongoDB\Driver\Monitoring\ServerChangedEvent" style="color:#EAB766">MongoDB\Driver\Monitoring\ServerChangedEvent</a></span> <span class="parameter" style="color:#3A95FF">\$event</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div>  <p class="simpara">   If the subscriber is registered, this method is called when a server's   description changes. For example, a server's type changing from secondary to   primary would cause its server description to change.  </p> </div> <div class="refsect1 parameters" id="refsect1-mongodb-driver-monitoring-sdamsubscriber.serverchanged-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">event</span> (<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.mongodb-driver-monitoring-serverchangedevent.php" class="type MongoDB\Driver\Monitoring\ServerChangedEvent" style="color:#EAB766">MongoDB\Driver\Monitoring\ServerChangedEvent</a></span>)</dt>    <dd>     <span class="simpara">      An event object encapsulating information about the changed server      description.     </span>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-mongodb-driver-monitoring-sdamsubscriber.serverchanged-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   没有返回值。  </p> </div> <div class="refsect1 errors" id="refsect1-mongodb-driver-monitoring-sdamsubscriber.serverchanged-errors">  <h3 class="title">错误／异常</h3>  <ul class="simplelist">   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span> on argument parsing errors.</li>  </ul> </div> <div class="refsect1 seealso" id="refsect1-mongodb-driver-monitoring-sdamsubscriber.serverchanged-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-monitoring-serverchangedevent.php" class="classname">MongoDB\Driver\Monitoring\ServerChangedEvent</a></span></li>   <li><span class="function">{@link MongoDB\Driver\Monitoring\addSubscriber()} - Registers a monitoring event subscriber globally</span></li>   <li><span class="function">{@link MongoDB\Driver\Manager::addSubscriber()} - Registers a monitoring event subscriber with this Manager</span></li>  </ul> </div></div>
 * 
     * Notification method for a server description change
     * @link https://www.php.net/manual/en/mongodb-driver-monitoring-sdamsubscriber.serverchanged.php
     */
    public function serverChanged(ServerChangedEvent $event): void;

    /**
 * <div id="mongodb-driver-monitoring-sdamsubscriber.serverclosed" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\Driver\Monitoring\SDAMSubscriber::serverClosed</h1>  <p class="verinfo">(mongodb &gt;=1.13.0)</p><p class="refpurpose"><span class="refname">MongoDB\Driver\Monitoring\SDAMSubscriber::serverClosed</span> — <span class="dc-title">Notification method for closing a server</span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-driver-monitoring-sdamsubscriber.serverclosed-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">abstract</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\Driver\Monitoring\SDAMSubscriber::serverClosed</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.mongodb-driver-monitoring-serverclosedevent.php" class="type MongoDB\Driver\Monitoring\ServerClosedEvent" style="color:#EAB766">MongoDB\Driver\Monitoring\ServerClosedEvent</a></span> <span class="parameter" style="color:#3A95FF">\$event</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div>  <p class="simpara">   If the subscriber is registered, this method is called when an existing   server is removed from the topology.  </p> </div> <div class="refsect1 parameters" id="refsect1-mongodb-driver-monitoring-sdamsubscriber.serverclosed-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">event</span> (<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.mongodb-driver-monitoring-serverclosedevent.php" class="type MongoDB\Driver\Monitoring\ServerClosedEvent" style="color:#EAB766">MongoDB\Driver\Monitoring\ServerClosedEvent</a></span>)</dt>    <dd>     <span class="simpara">      An event object encapsulating information about the closed server.     </span>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-mongodb-driver-monitoring-sdamsubscriber.serverclosed-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   没有返回值。  </p> </div> <div class="refsect1 errors" id="refsect1-mongodb-driver-monitoring-sdamsubscriber.serverclosed-errors">  <h3 class="title">错误／异常</h3>  <ul class="simplelist">   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span> on argument parsing errors.</li>  </ul> </div> <div class="refsect1 seealso" id="refsect1-mongodb-driver-monitoring-sdamsubscriber.serverclosed-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-monitoring-serverclosedevent.php" class="classname">MongoDB\Driver\Monitoring\ServerClosedEvent</a></span></li>   <li><span class="function">{@link MongoDB\Driver\Monitoring\addSubscriber()} - Registers a monitoring event subscriber globally</span></li>   <li><span class="function">{@link MongoDB\Driver\Manager::addSubscriber()} - Registers a monitoring event subscriber with this Manager</span></li>  </ul> </div></div>
 * 
     * Notification method for closing a server
     * @link https://www.php.net/manual/en/mongodb-driver-monitoring-sdamsubscriber.serverclosed.php
     */
    public function serverClosed(ServerClosedEvent $event): void;

    /**
 * <div id="mongodb-driver-monitoring-sdamsubscriber.serveropening" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\Driver\Monitoring\SDAMSubscriber::serverOpening</h1>  <p class="verinfo">(mongodb &gt;=1.13.0)</p><p class="refpurpose"><span class="refname">MongoDB\Driver\Monitoring\SDAMSubscriber::serverOpening</span> — <span class="dc-title">Notification method for opening a server</span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-driver-monitoring-sdamsubscriber.serveropening-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">abstract</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\Driver\Monitoring\SDAMSubscriber::serverOpening</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.mongodb-driver-monitoring-serveropeningevent.php" class="type MongoDB\Driver\Monitoring\ServerOpeningEvent" style="color:#EAB766">MongoDB\Driver\Monitoring\ServerOpeningEvent</a></span> <span class="parameter" style="color:#3A95FF">\$event</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div>  <p class="simpara">   If the subscriber is registered, this method is called when a new server is   added to the topology.  </p> </div> <div class="refsect1 parameters" id="refsect1-mongodb-driver-monitoring-sdamsubscriber.serveropening-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">event</span> (<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.mongodb-driver-monitoring-serveropeningevent.php" class="type MongoDB\Driver\Monitoring\ServerOpeningEvent" style="color:#EAB766">MongoDB\Driver\Monitoring\ServerOpeningEvent</a></span>)</dt>    <dd>     <span class="simpara">      An event object encapsulating information about the opened server.     </span>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-mongodb-driver-monitoring-sdamsubscriber.serveropening-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   没有返回值。  </p> </div> <div class="refsect1 errors" id="refsect1-mongodb-driver-monitoring-sdamsubscriber.serveropening-errors">  <h3 class="title">错误／异常</h3>  <ul class="simplelist">   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span> on argument parsing errors.</li>  </ul> </div> <div class="refsect1 seealso" id="refsect1-mongodb-driver-monitoring-sdamsubscriber.serveropening-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-monitoring-serveropeningevent.php" class="classname">MongoDB\Driver\Monitoring\ServerOpeningEvent</a></span></li>   <li><span class="function">{@link MongoDB\Driver\Monitoring\addSubscriber()} - Registers a monitoring event subscriber globally</span></li>   <li><span class="function">{@link MongoDB\Driver\Manager::addSubscriber()} - Registers a monitoring event subscriber with this Manager</span></li>  </ul> </div></div>
 * 
     * Notification method for opening a server
     * @link https://www.php.net/manual/en/mongodb-driver-monitoring-sdamsubscriber.serveropening.php
     */
    public function serverOpening(ServerOpeningEvent $event): void;

